"""DE0, G5: документ `DE0_REPORT.md` — ГЕНЕРАТОР из таблиц `DE0_*.csv` (в тексте нет вписанных чисел: каждое число — из таблицы). Первая строка — количественный ответ на главный вопрос; статус «диагностика, не отбор» — в ней же и в шапке."""
from __future__ import annotations

import pandas as pd

from models_v2.s15 import de0_io as IO

NOT_CHECKED = ["Одна бумага (SBER), h = 1, одна цель; другие тикеры и горизонты не смотрели (запрещено заданием).",
               "K2/K3 SBER: дизайн выбирался на SBER 2017–2021 (оговорка всех сравнений); окна 2022–2025 — оценка, не независимый тест.",
               "Группы (G3) и разложение (G2) объявлены до счёта и описательны: поправки на множественность нет, выводов для отбора из них не делается; одна пара — не статистика.",
               "Интервалы для Δ по группам не считались (малые n клеток); различия в клетках — ориентир, не доказательство.",
               "V1–V5: «вывод по правилам программы» — из `CMP_TESTS` (Δ к K2, Холм с N программы); собственные правила V1–V5 не пересчитывались. QLIKE 2018–2021 и `all_2018_2026` для V1–V6 — взвешенные годовые QLIKE по t⁺ (на одну дату больше, чем общие даты V7: d = 2018-01-03).",
               "Расстояние z (группа з) и признаки гребня z — из сохранённых энкодеров TCN-w5 Stage A (seed 0 для гребня, среднее 5 seeds для расстояния); оси z разных энкодеров не выровнены, поэтому гребень переучивается энкодером года дня прогноза.",
               "Гребень: одна объявленная λ = 100, без подбора; нелинейные зависимости (деревья, нейросети) не проверялись.",
               "EWMA₂₀ (группа ж) = α 2/21 — расшифровка «EWMA₂₀» принята как span = 20 (решение класса B, записано здесь)."]


def f(x, nd: int = 4) -> str:
    return "" if pd.isna(x) else ("%.*f" % (nd, x) if isinstance(x, float) else str(x))


def md(df: pd.DataFrame, nd: int = 4) -> str:
    out = ["| " + " | ".join(map(str, df.columns)) + " |", "|" + "---|" * len(df.columns)]
    out += ["| " + " | ".join(f(v, nd) for v in r) + " |" for r in df.itertuples(index=False)]
    return "\n".join(out)


def first_line(c: pd.DataFrame) -> str:
    """Количественный ответ: смена преимущества гибрида над K2 между окнами и доли четырёх причин (сумма = 100 %)."""
    parts, r0 = [], c.iloc[0]
    for _, r in c.iterrows():
        parts.append("%s: преимущество над K2 %+.4f → %+.4f (смена %+.4f); гибрид закрывает этот разрыв на %.0f %% → %.0f %%; смена = %+.4f (K2 оторвался от HAR-J, %.0f %% смены) %+.4f (выигрыш гибрида над HAR-J на недооценке u > 0, %.0f %%) %+.4f (на переоценке u ≤ 0, %.0f %%)" % (
            r["hybrid"], r["adv_2018_2021"], r["adv_2022_2025"], r["d_adv"], 100 * r["share_closed_2018_2021"], 100 * r["share_closed_2022_2025"], r["part_base"], 100 * r["share_base"], r["part_gu"], 100 * r["share_gu"], r["part_go"], 100 * r["share_go"]))
    return ("**[диагностика, не отбор] Почему гибриды теряют преимущество над XGBoost в 2022–2025**: разрыв QLIKE(HAR-J) − QLIKE(K2) вырос с %+.4f (2018–2021) до %+.4f (2022–2025), т.е. K2 оторвался от HAR-J на %.4f, а гибрид — поправка к HAR-J — закрывает лишь часть разрыва "
            "(adv = QLIKE(K2) − QLIKE(гибрид); плюс — гибрид лучше; доли смены в сумме 100 %%, большие доли разных знаков — следствие малой смены adv): " % (r0["delta_H_2018_2021"], r0["delta_H_2022_2025"], r0["delta_H_2022_2025"] - r0["delta_H_2018_2021"])
            + " | ".join(parts) + ".")


def build(t: dict) -> str:
    reg = t["DE0_REGISTRY"][["program", "id", "q_2018_2021", "q_2022_2025", "q_all_2018_2026", "cls", "verdict"]]
    tails, ro = t["DE0_TAILS"], t["DE0_RIDGE"]
    L = [first_line(t["DE0_CAUSES"]), "", "# DE0 — реестр V1–V7, разложение разрыва к XGBoost 2018–2025, диагностика остаточной ошибки (SBER, h = 1)", "",
         "Статус: диагностика, не отбор; DEVELOPMENT / HISTORICAL WALK-FORWARD, не независимый OOS; первая цифра — потолок. Сохранённые прогнозы, обучения и новых конфигураций нет (0). Окна — по году t⁺. Все числа — из `DE0_*.csv` (генератор `models_v2/s15/de0_doc.py`).", "",
         "## G2. Разложение разрыва к K2", "",
         "Смена преимущества = (−Δ_H изменение: K2 против HAR-J) + (изменение выигрыша гибрида над H: недооценка u > 0) + (то же: переоценка u ≤ 0). `DE0_CAUSES.csv`:", "", md(t["DE0_CAUSES"][["hybrid", "adv_2018_2021", "adv_2022_2025", "d_adv", "part_base", "part_gu", "part_go", "share_base", "share_gu", "share_go", "share_closed_2018_2021", "share_closed_2022_2025", "identity"]], 4), "",
         "(i) вклад года в Δ = mean l_гибрид − mean l_K2 за 2018–2025 (сумма вкладов = Δ, строка `итого`):", "", md(t["DE0_GAP_YEARS"], 5), "",
         "(ii) разрыв базы Δ_H = QLIKE(H) − QLIKE(K2) и доля, закрытая гибридом (>1 — гибрид лучше K2):", "", md(t["DE0_GAP_BASE"], 4), "",
         "(iii) QLIKE = under (u > 0, недооценка) + over (u ≤ 0, переоценка); mean_u — смещение:", "", md(t["DE0_UNDER_OVER"], 4), "",
         "(iv) доля Δ от 1 % и 5 % дат с наибольшим |l_гибрид − l_K2| (share_of_delta = Σ по крайним / Σ всех; delta_ex_top — Δ без них):", "", md(tails[["hybrid", "window", "q", "k", "delta", "delta_top_sum", "delta_ex_top", "share_of_delta", "top_worse", "identity"]], 4), "",
         "## G1. Реестр V1–V7", "", "QLIKE из таблиц программ; `all_2018_2026` — общая история V7 (V1–V6 пересчитано из годовых QLIKE). Полная таблица — `DE0_REGISTRY.csv` (источник, проверка равенства — столбцы `check_*`).", "", md(reg, 4), "",
         "## G3. Группы (терцили по прошлому, первые 250 дат без группы)", "", md(t["DE0_GROUPS"], 4), "",
         "Ответы на вопросы 1–8 п. 3 блока Ж-239 (`DE0_QUESTIONS.csv`):", ""]
    L += ["- **%s** [%s]: %s" % (r.q, r.window, r.answer) for r in t["DE0_QUESTIONS"].itertuples()]
    L += ["", "## G4. Устойчивость и предсказуемость", "", "Автокорреляция дифференциала потерь (лаги 1–5):", "", md(t["DE0_ACF"], 4), "", "Серии подряд d_t > 0:", "", md(t["DE0_RUNS"], 3), "",
          "PIT-гребень (расширяющееся окно, месячная переоценка, λ = 100), R² вне выборки по году t⁺ — пул:", "", md(ro[ro["year"] == "пул"], 4), "", "По годам — `DE0_RIDGE.csv`.", "", "## Что не проверено", ""]
    L += ["- " + s for s in NOT_CHECKED]
    return "\n".join(L) + "\n"


def write(t: dict) -> None:
    IO.DOC.write_text(build(t), encoding="utf-8")
